## Code Example
```javascript
// Example test outline (Playwright + API stubs)
test('tenant-scoped data export end-to-end', async ({ page, api, storage }) => {
  await loginAsAdmin(page);
  await page.click('#start-export');
  await page.waitForResponse(r => r.url.includes('/exports/').and(r.status() === 200));
  const status = await api.get(`/exports/${tenantId}/status`);
  expect(status).toHaveProperty('state', 'COMPLETED');
  const blob = await storage.getBlob(`exports/${tenantId}/data.json`);
